#include <tbb/concurrent_vector.h>

std::vector<Record> find_large(const std::vector<Record>& records, std::size_t threshold) {
  tbb::concurrent_vector<Record> hits;
  tbb::parallel_for(tbb::blocked_range<std::size_t>(0, records.size()),
      [&](const tbb::blocked_range<std::size_t>& r) {
        for (std::size_t i = r.begin(); i != r.end(); ++i) {
          if (records[i].bytes >= threshold) hits.push_back(records[i]);
        }
      });
  return std::vector<Record>(hits.begin(), hits.end());
}

#include <tbb/parallel_reduce.h>

std::vector<Record> find_large(const std::vector<Record>& records, std::size_t threshold) {
  return tbb::parallel_reduce(
      tbb::blocked_range<std::size_t>(0, records.size()), std::vector<Record>{},
      [&](const tbb::blocked_range<std::size_t>& r, std::vector<Record> acc) {
        for (std::size_t i = r.begin(); i != r.end(); ++i) {
          if (records[i].bytes >= threshold) acc.push_back(records[i]);
        }
        return acc;
      },
      [](std::vector<Record> left, const std::vector<Record>& right) {
        left.insert(left.end(), right.begin(), right.end());
        return left;
      });
}

#include <functional>

#include <tbb/combinable.h>

std::size_t total_bytes(const std::vector<Record>& records) {
  tbb::combinable<std::size_t> partial([] { return std::size_t{0}; });
  tbb::parallel_for(tbb::blocked_range<std::size_t>(0, records.size(), 1024),
      [&](const tbb::blocked_range<std::size_t>& r) {
        std::size_t& local = partial.local();
        for (std::size_t i = r.begin(); i != r.end(); ++i) local += records[i].bytes;
      });
  return partial.combine(std::plus<>{});
}
